 let initialLoadControls=null;
 async function load(){if(!initialLoadControls)initialLoadControls=all('button,input,textarea,select').map(e=>({e,disabled:e.disabled}));const controls=initialLoadControls;controls.forEach(v=>v.e.disabled=true);const loading=panel('book-load');loading.replaceChildren(UI.components.loading({mode:'skeleton',label:'正在打开共同回忆…'}));screen.setAttribute('aria-busy','true');await new Promise(resolve=>setTimeout(resolve,400));try{if(UI.failNext('book-load'))throw new Error('回忆册暂时打不开');await document.fonts.ready;controls.forEach(v=>v.e.disabled=v.disabled);loading.remove();render();PrototypeBookV2.enhance(n,screen);screen.setAttribute('aria-busy','false');}catch(e){screen.setAttribute('aria-busy','false');if(!loading.isConnected)screen.append(loading);const error=UI.components.state({kind:'error',title:e.message,message:'当前数据未修改，可以重新加载后继续。',action:'重新加载',onAction:()=>{loading.remove();load();}});error.append(UI.components.button('返回书架',()=>go(1,{},null),{variant:'text'}));loading.replaceChildren(error);}}
